PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON; PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY,applied_at INTEGER NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1,unixepoch()*1000);
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admins(username TEXT PRIMARY KEY,password_hash BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS collectors(source_id TEXT PRIMARY KEY,label TEXT NOT NULL,token_hash TEXT UNIQUE NOT NULL,revoked INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS capture_sessions(source_id TEXT NOT NULL,session_id TEXT NOT NULL,context TEXT NOT NULL,PRIMARY KEY(source_id,session_id));
CREATE TABLE IF NOT EXISTS messages(source_id TEXT NOT NULL,session_id TEXT NOT NULL,message_id TEXT NOT NULL,revision INTEGER NOT NULL,stable_hash TEXT NOT NULL,payload TEXT NOT NULL,event_at INTEGER NOT NULL,received_at INTEGER NOT NULL,PRIMARY KEY(source_id,session_id,message_id,revision));
CREATE INDEX IF NOT EXISTS messages_time ON messages(event_at);
CREATE TABLE IF NOT EXISTS configs(id TEXT PRIMARY KEY,payload TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,status TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,full INTEGER NOT NULL,error TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,finished_at INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS jobs_status ON jobs(status,created_at);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,event_at INTEGER NOT NULL,payload TEXT NOT NULL,sources TEXT NOT NULL,generation INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_time ON events(event_at);
CREATE TABLE IF NOT EXISTS event_links(source_id TEXT NOT NULL,session_id TEXT NOT NULL,message_id TEXT NOT NULL,event_id TEXT NOT NULL,PRIMARY KEY(source_id,session_id,message_id));
CREATE INDEX IF NOT EXISTS event_links_event ON event_links(event_id);
CREATE TABLE IF NOT EXISTS overrides(event_id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit(request_id TEXT PRIMARY KEY,kind TEXT NOT NULL,event_id TEXT NOT NULL,payload TEXT NOT NULL,created_at INTEGER NOT NULL);
